/* ==================== SMS segments ==================== */

// GSM 03.38 basic character set (one septet each) and the extension table
// (two septets: escape + char). Anything else forces UCS-2 for the whole SMS.
var SMS_GSM7_BASIC = '@£$¥èéùìòÇ\nØø\rÅåΔ_ΦΓΛΩΠΨΣΘΞÆæßÉ !"#¤%&\'()*+,-./0123456789:;<=>?' +
  '¡ABCDEFGHIJKLMNOPQRSTUVWXYZÄÖÑÜ§¿abcdefghijklmnopqrstuvwxyzäöñüà';
var SMS_GSM7_EXT = '^{}\\[~]|€\f';
var SMS_LIMITS = { gsm7: { single: 160, part: 153 }, ucs2: { single: 70, part: 67 } };
// Longest message a campaign may send, in segments (a phone splits and joins them).
var SMS_MAX_SEGMENTS = 10;

/**
 * { encoding: 'gsm7'|'ucs2', units, segments, perSegment, remaining, unicodeChars: [...] }
 * units: septets for GSM-7 (extension chars count 2), UTF-16 code units for
 * UCS-2 (an emoji counts 2) - what the network actually counts.
 */
function smsSegmentInfo(text) {
  var s = String(text == null ? '' : text);
  var septets = 0, unicode = [];
  for (var i = 0; i < s.length; i++) {
    var ch = s.charAt(i);
    if (SMS_GSM7_BASIC.indexOf(ch) !== -1) septets += 1;
    else if (SMS_GSM7_EXT.indexOf(ch) !== -1) septets += 2;
    else {
      var cp = s.codePointAt ? s.codePointAt(i) : s.charCodeAt(i);
      var whole = cp > 0xffff ? s.substr(i, 2) : ch;
      if (unicode.indexOf(whole) === -1) unicode.push(whole);
      if (cp > 0xffff) i++;
    }
  }
  var encoding = unicode.length ? 'ucs2' : 'gsm7';
  var units = encoding === 'gsm7' ? septets : s.length;
  var lim = SMS_LIMITS[encoding];
  var segments = units === 0 ? 0 : (units <= lim.single ? 1 : Math.ceil(units / lim.part));
  var perSegment = segments <= 1 ? lim.single : lim.part;
  var remaining = segments === 0 ? lim.single : segments * perSegment - units;
  return { encoding: encoding, units: units, segments: segments, perSegment: perSegment, remaining: remaining, unicodeChars: unicode };
}

/* ==================== Phone numbers ==================== */

// Kiribati: country code 686, national numbers 8 digits. Mobile numbers start
// 730 or 630 - the same rule checkout uses (isCustomerPhoneValid, Orders.gs).
var SMS_KI_CODE = '686';
var SMS_KI_NATIONAL_LEN = 8;

/**
 * Checks a number without ever changing its digits.
 * { status: 'ok'|'check'|'invalid'|'missing', e164, country: 'KI'|'intl'|'', mobile: bool, note }
 *  ok      a Kiribati mobile number, or a plausible international number
 *  check   a Kiribati number that is not a mobile (likely a landline - cannot take SMS)
 *  invalid wrong length or not a number - left for the user to correct, never guessed
 * e164 is +<country><number>: the only change ever made is adding +686 to a
 * local number written without it.
 */
function smsNormalisePhone(raw) {
  var original = String(raw == null ? '' : raw).trim();
  if (!original) return { status: 'missing', e164: '', country: '', mobile: false, note: 'No number' };
  var s = original.replace(/[\s()\-.\/]/g, '');
  var intl = false;
  if (s.charAt(0) === '+') { intl = true; s = s.slice(1); }
  else if (s.slice(0, 2) === '00') { intl = true; s = s.slice(2); }
  if (!/^\d+$/.test(s)) return { status: 'invalid', e164: '', country: '', mobile: false, note: 'Not a phone number' };

  var national = null;
  if (s.slice(0, 3) === SMS_KI_CODE && (intl || s.length === SMS_KI_CODE.length + SMS_KI_NATIONAL_LEN)) national = s.slice(3);
  else if (!intl) national = s;

  if (national !== null) {
    if (national.length !== SMS_KI_NATIONAL_LEN) {
      return { status: 'invalid', e164: '', country: 'KI', mobile: false, note: 'Kiribati numbers have ' + SMS_KI_NATIONAL_LEN + ' digits' };
    }
    var mobile = /^(730|630)/.test(national);
    return { status: mobile ? 'ok' : 'check', e164: '+' + SMS_KI_CODE + national, country: 'KI', mobile: mobile,
      note: mobile ? '' : 'Not a Kiribati mobile number (may be a landline)' };
  }
  if (s.length < 7 || s.length > 15) return { status: 'invalid', e164: '', country: 'intl', mobile: false, note: 'International numbers have 7 to 15 digits' };
  return { status: 'ok', e164: '+' + s, country: 'intl', mobile: true, note: 'International number' };
}

/* ==================== Personalisation ==================== */

var SMS_FIELDS = ['first_name', 'last_name', 'business_name', 'island', 'village'];

/**
 * Fills {first_name}, {first_name|friend} (with a fallback) and the other
 * SMS_FIELDS from a contact { firstName, lastName, businessName, island, village }.
 * { text, missing: [fields with no value and no fallback], unknown: [{tags} we do not know] }
 */
function smsRender(template, contact, defaults) {
  var c = contact || {};
  var d = defaults || {};
  var values = { first_name: c.firstName, last_name: c.lastName, business_name: c.businessName, island: c.island, village: c.village };
  var missing = [], unknown = [];
  var text = String(template == null ? '' : template).replace(/\{([a-z_]+)(\|([^{}]*))?\}/g, function (all, field, hasFb, fallback) {
    if (SMS_FIELDS.indexOf(field) === -1) { if (unknown.indexOf(field) === -1) unknown.push(field); return all; }
    var v = String(values[field] == null ? '' : values[field]).trim();
    if (v) return v;
    if (hasFb) return fallback;
    if (d[field]) return String(d[field]);
    if (missing.indexOf(field) === -1) missing.push(field);
    return '';
  });
  return { text: text.replace(/ {2,}/g, ' ').replace(/ ([,.!?])/g, '$1').trim(), missing: missing, unknown: unknown };
}

